import type { Portrait } from './types';

/** Loads public/portrait.json (generated by scripts/stipple.py): 5 bytes per point, x/y as uint16, tone as uint8. */
export async function loadPortrait(url: string): Promise<Portrait | null> {
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = (await res.json()) as { aspect: number; n: number; b64: string };
    const bin = atob(data.b64);
    const n = Math.floor(bin.length / 5);
    const points = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const o = i * 5;
      points[i * 3] = (bin.charCodeAt(o) | (bin.charCodeAt(o + 1) << 8)) / 65535;
      points[i * 3 + 1] = (bin.charCodeAt(o + 2) | (bin.charCodeAt(o + 3) << 8)) / 65535;
      points[i * 3 + 2] = bin.charCodeAt(o + 4) / 255;
    }
    return { aspect: data.aspect, n, points };
  } catch {
    return null;
  }
}

/** Waits for the fonts the particles sample from, but never longer than `timeoutMs`. */
export async function waitForFonts(timeoutMs = 1500): Promise<void> {
  if (!document.fonts?.load) return;
  const loads = Promise.all([
    document.fonts.load('800 80px "Archivo"', 'Teaching machines'),
    document.fonts.load('700 120px "Anek Bangla"', 'আনজির সহজ Anjir'),
  ]).then(() => undefined, () => undefined);
  await Promise.race([loads, new Promise<void>((r) => setTimeout(r, timeoutMs))]);
}
